<?php require_once __DIR__.'/config/db.php';$slug=trim($_GET['slug']??'');$s=$pdo->prepare('SELECT p.*,c.name category_name,c.slug category_slug FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=?');$s->execute([$slug]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Product not found');}$page_title=$p['name'].' — MediNova';require __DIR__.'/includes/store_header.php';?><section class="form-page"><div class="two-col" style="align-items:center"><div class="product-image-wrap"><?php if($p['image']): ?><img src="<?=BASE_URL?><?=e($p['image'])?>" alt="<?=e($p['name'])?>"><?php else: ?><div class="medicine-art"><i class="pill"></i><i class="pill p2"></i></div><?php endif; ?></div><div><p class="kicker"><?=e($p['category_name']??'Pharmacy')?></p><h1 style="font-size:clamp(48px,7vw,90px);line-height:.9;margin:10px 0 20px"><?=e($p['name'])?></h1><p style="color:#929b93;line-height:1.8"><?=nl2br(e($p['description']??''))?></p><h2 style="font:500 28px 'Space Grotesk';margin:25px 0">Rs. <?=number_format((float)$p['price'])?></h2><p style="color:#7e877f;font-size:12px"><?=((int)$p['stock'])?> in stock</p><button class="btn btn-light add-cart" data-id="<?=$p['id']?>" style="margin-top:15px">Add to bag +</button></div></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
